/**
 * Command router. `ctx` provides shared runtime handles:
 *   { bot, orchestrator }
 */
export function createCommandHandler(ctx) {
  const { bot, orchestrator } = ctx;
  const reply = (chatId, text, extra) => bot.sendMessage(chatId, text, extra);

  const commands = {
    // ------------------------------------------------- diagnose & self-repair
    // Nothing here changes code on its own: the agent can only PROPOSE a fix
    // (propose_code_fix); /approve is the single place a proposal is applied.
    async diagnose(chatId, args) {
      const sym = args[0] ? String(args[0]).toUpperCase() : null;
      const d = await diagnose({ symbol: sym });
      if (d.noPositionsTraced) {
        return reply(chatId, [
          bold('🩺 Diagnose'),
          md(`No open position has been evaluated by the guard${sym ? ` for ${sym}` : ''} since this process started.`),
          md(`Recent failure events: ${d.recentFailureEvents.length}, warn/error logs: ${d.recentWarnErrorLogs.length}.`),
          '', italic('Ask me in plain words why something did not happen and I will dig into the evidence.'),
        ].join('\n'));
      }
      const lines = [bold('🩺 Diagnose')];
      for (const p of d.positions) {
        lines.push('', bold(`${p.symbol} ${p.side}`) + md(`  ·  checked ${p.lastPassSecondsAgo}s ago  ·  ${p.category}`));
        lines.push(md(p.headline));
        for (const r of p.reasons) lines.push(md('• ' + r));
      }
      const fails = d.recentFailureEvents.slice(0, 4);
      if (fails.length) {
        lines.push('', bold('Recent failures'));
        for (const e of fails) lines.push(md(`• ${e.kind}${e.symbol ? ' ' + e.symbol : ''}: ${JSON.stringify(e.payload).slice(0, 160)}`));
      }
      if (d.positions.some((p) => p.category === 'possible_code_bug')) {
        lines.push('', italic('This looks like a code problem. Tell me to investigate and I will propose a fix for your approval.'));
      }
      return reply(chatId, lines.join('\n'));
    },

    async autopsy(chatId, args) {
      const a0 = String(args[0] || '7');
      const r = await autopsy({ days: /h$/i.test(a0) ? (parseFloat(a0) / 24) : parseFloat(a0) });
      if (!r.trades) return reply(chatId, md(`No closed trades in the trades table for the last ${r.days} days.`));
      const lines = [bold(`🔬 Autopsy · last ${r.days < 1 ? Math.round(r.days * 24) + 'h' : r.days + 'd'}`),
        md(`${r.trades} trades · ${r.wins}W/${r.losses}L · PnL ${r.pnl.toFixed(4)} (as recorded)`),
        md(`win rate ${(r.winRate * 100).toFixed(0)}% · needs ${(r.breakEvenWinRate * 100).toFixed(0)}% to break even`),
        md(`avg win ${r.avgWin.toFixed(4)} · avg loss ${r.avgLoss.toFixed(4)} · move win ${r.avgWinMovePct.toFixed(2)}% / loss ${r.avgLossMovePct.toFixed(2)}%`),
        md(`planned stop ${r.medianPlannedSlPct.toFixed(2)}% · planned TP ${r.medianPlannedTpPct.toFixed(2)}% (median)`),
        md(`95% range for win rate ${(r.winRateCI[0] * 100).toFixed(0)}-${(r.winRateCI[1] * 100).toFixed(0)}% · price-terms break-even incl. fees ${Number.isFinite(r.breakEvenWinRatePriceFee) ? (r.breakEvenWinRatePriceFee * 100).toFixed(0) + '%' : '?'}`),
        md(`avg notional win ${r.avgNotionalWin.toFixed(2)} / loss ${r.avgNotionalLoss.toFixed(2)} USDT`),
        ...(r.stopOuts.n ? [md(`stop-outs ${r.stopOuts.n}: ${r.stopOuts.reachedHalfTarget} went half-way to TP first · ${r.stopOuts.neverWorked} never worked · best move before stop (median) ${r.stopOuts.medianBestMovePct.toFixed(2)}% · went past the TP: ${r.stopOuts.beyondTpHi} (${r.stopOuts.beyondTpLo} excl. entry minute)`)] : []),
        ...(r.stopOuts.n ? [md(`breakeven check uses TODAY's setting (${r.breakevenRoi}% ROI), not the one each trade ran with: ${r.stopOuts.armedButLost} stop-outs reached it and still lost · ${r.stopOuts.neverArmed} never reached it`), md(`stop-outs that went at least ${r.stopOuts.bestMoveBuckets.map((b) => `${b.atLeastPct}% → ${b.stopOuts}`).join(' · ')}`)] : []),
        md(`direction: ${r.longs} LONG / ${r.shorts} SHORT`),
        ...(r.entryContext ? [md(`entries at the extreme of the last 2h range: ${r.entryContext.chasing}/${r.entryContext.n} · median chase wins ${r.entryContext.medianChaseWins.toFixed(2)} vs losses ${r.entryContext.medianChaseLosses.toFixed(2)} (1 = bought the top / sold the bottom)`)] : []),
        '', bold('By leverage')].concat(r.leverages.slice(0, 6).map((x) => md(`• ${x.lev}: ${x.n} trades, ${x.wins} wins, PnL ${x.pnl.toFixed(4)}`)), ['', bold('By close reason')]);
      for (const x of r.reasons.slice(0, 8)) lines.push(md(`• ${x.reason}: ${x.n} trades, ${x.wins} wins, PnL ${x.pnl.toFixed(4)}, avg move ${x.avgMovePct.toFixed(2)}%`));
      lines.push('', bold('Findings'), ...r.findings.map((f) => md('• ' + f)));
      return reply(chatId, lines.join('\n'));
    },

    async tpsl(chatId, args) {
      if (!args[0]) return reply(chatId, md('Usage: /tpsl SYMBOL  (an open position)'));
      const r = await auditSymbol(args[0]);
      if (!r.open) return reply(chatId, md(`No open ${r.symbol} position.`));
      const lines = [bold(`🎯 TP/SL audit · ${r.symbol} ${r.side}`),
        md(`qty ${r.qty} · entry ${r.entry} · stop distance ${r.plannedStopDistPct == null ? '?' : r.plannedStopDistPct.toFixed(2)}% · price tick ${r.priceTick} = ${r.tickPctOfPrice.toFixed(2)}% of price`),
        md(`method ${r.tpslMethod} · ladder setting "${r.ladderSetting}"`), '', bold('Expected rungs')];
      for (const x of r.expected) lines.push(md(`• ${x.share}% @ ${x.r}R → ${x.price} (qty ${x.qty.toFixed(0)})`));
      lines.push('', bold('On the exchange'));
      for (const x of r.rows) lines.push(md(`• ${x.tpPrice != null ? `TP ${x.tpPrice} qty ${x.tpQty ?? 'whole'}` : ''}${x.slPrice != null ? `SL ${x.slPrice} qty ${x.slQty ?? 'whole'}` : ''}`));
      lines.push('', bold('Findings'), ...(r.flags.length ? r.flags.map((f) => md('• ' + f)) : [md('• ladder matches the exchange')]));
      return reply(chatId, lines.join('\n'));
    },

    async repairs(chatId) {
      const rows = await listProposals(10);
      if (!rows.length) return reply(chatId, md('No repair proposals yet.'));
      return reply(chatId, [bold('🛠 Repair proposals'), ...rows.map((r) => md(`#${r.id} [${r.status}] ${r.title}`)),
        '', italic('/repair <id> shows the diff · /approve <id> · /reject <id> · /rollback <id>')].join('\n'));
    },

    async repair(chatId, args) {
      const p = await getProposal(args[0]);
      if (!p) return reply(chatId, md('Usage: /repair <id>'));
      const body = String(p.diff).slice(0, 3200).replace(/[`\\]/g, '\\$&');
      return reply(chatId, [bold(`🛠 #${p.id} [${p.status}] ${p.title}`), md(p.diagnosis.slice(0, 700)), '', '```\n' + body + '\n```',
        p.status === 'pending' ? italic(`/approve ${p.id}  ·  /reject ${p.id}`) : ''].join('\n'));
    },

    async approve(chatId, args) {
      const id = args[0];
      if (!id) return reply(chatId, md('Usage: /approve <id> [push]'));
      await reply(chatId, italic('Applying, then running the test suite - this can take a minute…'));
      const r = await applyProposal(id, { push: args[1] === 'push' });
      if (!r.ok) {
        return reply(chatId, [bold(`❌ #${id} NOT applied - tests got worse, files restored`),
          md(`failed suites before ${r.before.failed}, after ${r.after.failed}`), '```\n' + String(r.after.tail).slice(-1200).replace(/[`\\]/g, '\\$&') + '\n```'].join('\n'));
      }
      return reply(chatId, [bold(`✅ #${id} applied`), md(`files: ${r.files.join(', ')}`),
        md(`tests: ${r.after.failed} failing (was ${r.before.failed})`), md(`git: ${r.git.note}${r.git.commit ? ' ' + r.git.commit : ''}`),
        '', md('The fix is on disk but the running process still has the OLD code. /restart loads it (needs `npm run start:guarded`, systemd or pm2 to bring it back; open positions keep their exchange-side stops).'),
        md(`/rollback ${id} undoes it.`)].join('\n'));
    },

    async reject(chatId, args) {
      await rejectProposal(args[0]);
      return reply(chatId, md(`Proposal #${args[0]} rejected. Nothing was changed.`));
    },

    async rollback(chatId, args) {
      const r = await rollbackProposal(args[0]);
      return reply(chatId, [bold(`⏪ #${args[0]} rolled back`), md(`restored: ${r.files.join(', ')}`), md('/restart to load the restored code.')].join('\n'));
    },

    async restart(chatId) {
      await reply(chatId, md('Restarting now. If no supervisor is running (start:guarded / systemd / pm2) I will stay down - start me again by hand.'));
      restartProcess();
    },

