          mdt`   entry ${fmtNum(p.entryPrice, 6)} → exit ${fmtNum(p.closePrice, 6)}  ·  fee ${p.fee}  ·  funding ${p.funding}`,
          mdt`   ${new Date(Number(p.mtime)).toISOString().replace('T', ' ').slice(0, 16)}`,
