import { reconcileAfterBoot } from './ai/repair.js';
import { config, assertBootConfig } from './config.js';
import { createLogger } from './logger.js';
import { connect as connectDb, migrate, seedSettings, loadSettings, settings, close as closeDb, logEvent } from './db/index.js';
import { startHealthServer, stopHealthServer, setHealth } from './health.js';
import bitunix from './exchange/bitunix.js';
import feed from './exchange/ws.js';
import ai from './ai/providers.js';
import { initMcpTools } from './ai/tools.js';
import TelegramBot from './telegram/bot.js';
import { createCommandHandler } from './telegram/commands.js';
import Orchestrator from './orchestrator.js';
import { mdt, md } from './telegram/format.js';
import { STRATEGY_COUNT } from './strategies/index.js';

const log = createLogger('boot');

const BANNER = `
╔══════════════════════════════════════════════════════╗
║   BITUNIX  AI  AGENT  TRADER                         ║
║   agentic · multi-strategy · live · neon · mcp       ║
╚══════════════════════════════════════════════════════╝`;

async function main() {
  console.log(BANNER);
  log.warn('LIVE TRADING — there is no dry-run mode. Real orders will be placed.');

  // Bind the port first: the platform's health probe starts the moment the
  // container is up, and a slow database must not read as a dead service.
  startHealthServer();

  assertBootConfig();

  // ---- database -------------------------------------------------------
  setHealth('connecting to database');
  await connectDb();
  setHealth('migrating');
  await migrate();
  await seedSettings();
  await loadSettings();
  log.info('database connected, settings loaded');

  // ---- exchange sanity check -----------------------------------------
  const pairs = await bitunix.getTradingPairs();
  log.info(`bitunix reachable — ${pairs.length} futures pairs`);
  const acc = await bitunix.getAccount();
  const a = Array.isArray(acc) ? acc[0] : acc;
  log.info(`account ok — available ${a?.available} ${a?.marginCoin}, position mode ${a?.positionMode}`);

  // ---- AI -------------------------------------------------------------
  if (!ai.available) throw new Error('No AI provider key configured');
  await ai.refreshModels();

  // external MCP servers from mcp.json — optional, never fatal
  const mcpTools = await initMcpTools();
  if (mcpTools.length) log.info(`MCP: ${mcpTools.length} external tool(s) loaded`);
  log.info('models: ' + ai.status().map((p) => `${p.provider}=${p.model}`).join(' '));

  // ---- websocket feed --------------------------------------------------
  // start() opens BOTH sockets and queues the private channel set; the public
  // ticker/kline subscriptions are added by the scanner once the universe is
  // known (watchSymbols() in buildUniverse).
  feed.start();

  // ---- telegram --------------------------------------------------------
  // start() degrades instead of throwing: a bad bot token must not take the
  // trader down, because the trader is what manages real positions.
  const bot = new TelegramBot();
  const me = await bot.start();

  const chatIds = config.telegram.allowed.length
    ? config.telegram.allowed
    : [];
  if (!chatIds.length) {
    log.warn('TELEGRAM_ALLOWED_CHAT_IDS is empty — the agent will answer anyone and cannot push reports. Set it!');
  }

  const orchestrator = new Orchestrator({ bot, chatIds });
  bot.onMessage(createCommandHandler({ bot, orchestrator }));

  const s = settings();
  // No bot, no chat ids, or a degraded bot — there is nobody to tell. Say it in
  // the log instead of crashing on me.username.
  if (bot.degraded) {
    log.error('running headless — Telegram is down, so no reports and no /commands. Fix TELEGRAM_BOT_TOKEN to restore control.');
  } else if (!chatIds.length) {
    log.warn('no allowed chat ids — startup notice not sent');
  } else {
    for (const id of chatIds) {
      await bot.sendMessage(id, [
        mdt`🟢 ${config.agentName} is live as @${me.username}.`,
        mdt`${pairs.length} pairs · ${s.leverage}x ${s.margin_mode} ${s.position_mode} · order unit ${s.order_unit}`,
        mdt`gates ${s.min_agreement}/${STRATEGY_COUNT} @ ${s.min_confidence}% · cooldown ${s.cooldown_min}m · reversal ${s.reversal_enabled ? s.reversal_confidence + '%' : 'off'}`,
        mdt`auto trade ${s.auto_trade ? 'ON' : 'OFF'} · thinking ${s.thinking_level}`,
        mdt`models: ${ai.status().map((p) => p.model).join(', ')}`,
        '',
        md('/help for commands — or just talk to me.'),
      ].join('\n'));
    }
  }

  // An approved repair that crashed the new code on boot was rolled back by
  // scripts/run-guarded.js; tell the operator instead of leaving it silent.
  try {
    const rb = await reconcileAfterBoot();
    if (rb) for (const id of chatIds) {
      await bot.sendMessage(id, mdt`⏪ Repair #${rb.id} was rolled back automatically: the new code failed to start (${rb.reason}). The previous files are running again.`);
    }
  } catch (e) { log.warn(`repair reconcile: ${e.message}`); }

  orchestrator.start();
  await logEvent('agent_started', { pairs: pairs.length, settings: s });
  setHealth('running');
  log.info('🚀 agent running');

  // ---- shutdown --------------------------------------------------------
  const shutdown = async (sig) => {
    log.warn(`${sig} — shutting down (open positions are NOT closed)`);
    setHealth('shutting down');
    orchestrator.stop();
    bot.stop();
    feed.stop();
    stopHealthServer();
    try { await logEvent('agent_stopped', { signal: sig }); } catch {}
    await closeDb();
    process.exit(0);
  };
  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('unhandledRejection', (e) => log.error('unhandledRejection:', e?.stack || e));
  process.on('uncaughtException', (e) => log.error('uncaughtException:', e?.stack || e));
}

main().catch((e) => {
  // A crashed deploy shows only this. Make it the whole story: what broke,
  // and what to change — not a stack trace through the pg driver.
  log.error(e.message);
  for (const hint of e.hints || []) log.error(`   → ${hint}`);
  if (!e.hints?.length && e.stack) log.error(e.stack);
  if (e.cause?.stack && process.env.LOG_LEVEL === 'debug') log.error(e.cause.stack);
  setHealth('crashed', e.message);
  process.exit(1);
});

/**
 * A health endpoint, for the benefit of the host rather than the trader.
 *
 * The agent is a worker: it polls Telegram and the exchange and never needs
 * to listen on a socket. Hosting platforms do not know that. Railway, Render
 * and friends watch for a process that binds `$PORT`, and a service that
 * never does is reported as unhealthy and restarted — a trading loop killed
 * every couple of minutes for the crime of not being a web server.
 *
 * So: if the platform gave us a PORT, answer it. Off by default locally.
 */
import http from 'node:http';
import { config } from './config.js';
import { createLogger } from './logger.js';
import { dbInfo } from './db/index.js';

const log = createLogger('health');
const startedAt = Date.now();

let server = null;
let state = { phase: 'booting', detail: null };

/** Boot progress, surfaced at /health so a failing deploy is readable. */
export function setHealth(phase, detail = null) {
  state = { phase, detail };
}

function snapshot() {
  const db = dbInfo();
  return {
    ok: state.phase === 'running' && db.connected,
    agent: config.agentName,
    phase: state.phase,
    detail: state.detail,
    uptimeSec: Math.round((Date.now() - startedAt) / 1000),
    db: { connected: db.connected, host: db.host ?? null, database: db.database ?? null, ssl: db.ssl, source: db.source },
  };
}

export function startHealthServer() {
  if (!config.http.enabled || server) return null;
  const port = config.http.port || 8080;

  server = http.createServer((req, res) => {
    const body = snapshot();
    // Unhealthy means "this deploy is dead", not "the database blipped": the
    // data layer degrades to neutral defaults on purpose, and having the host
    // restart a live trading loop over a transient Neon hiccup would be worse
    // than the hiccup. Booting counts as healthy so a slow start is not
    // mistaken for a failed one.
    const code = body.phase === 'crashed' ? 503 : 200;
    res.writeHead(code, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
    res.end(JSON.stringify(body, null, 2));
  });

  // A health server that cannot bind must never take the trader down with it.
  server.on('error', (e) => {
    log.warn(`health server disabled: ${e.message}`);
    server = null;
  });

  // 0.0.0.0, not localhost: the platform's probe comes from outside the container.
  server.listen(port, '0.0.0.0', () => log.info(`health endpoint on :${port}/health`));
  return server;
}

export function stopHealthServer() {
  try { server?.close(); } catch {}
  server = null;
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import pg from 'pg';
import { config } from '../config.js';
import { createLogger } from '../logger.js';
import {
  explainDbError, isRetryable, parseTarget, probeSsl, redactUrl,
  sslCorrection, sslLabel, sslPolicy, stripSslParams, validateUrl,
} from './connection.js';

const log = createLogger('db');
const __dirname = path.dirname(fileURLToPath(import.meta.url));

const int = (v, d) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Number(v) : d);
const CONNECT_ATTEMPTS = int(process.env.DB_CONNECT_ATTEMPTS, 10);
const CONNECT_TIMEOUT_MS = int(process.env.DB_CONNECT_TIMEOUT_MS, 15_000);
const POOL_MAX = int(process.env.DB_POOL_MAX, 5);

const dbUrl = config.db.url;
const dbSource = config.db.source;

/**
 * TLS is a property of the *server*, not of our preference, so it is not
 * frozen at import time: we start from the best guess and let the handshake
 * correct us (see `connect`). Private Railway Postgres and public Neon then
 * both work from the same code with no flags — including the very common case
 * of a `?sslmode=require` copied off a Neon example onto an internal host.
 *
 * The exception is `verify-ca`/`verify-full`: downgrading a stated security
 * requirement because the server asked nicely is how you get MITM'd, so that
 * one is pinned and a mismatch is left to fail loudly.
 */
const policy = sslPolicy(dbUrl);
let ssl = policy.ssl;
const sslPinned = policy.pinned;

function buildPool() {
  const p = new pg.Pool({
    // sslmode stripped: the driver would otherwise let the URL overrule `ssl`
    // below, which is the decision we just took. See stripSslParams().
    connectionString: stripSslParams(dbUrl),
    ssl,
    max: POOL_MAX,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: CONNECT_TIMEOUT_MS,
    keepAlive: true,            // PaaS networks drop idle TCP without it
  });
  p.on('error', (e) => log.warn('pool error:', e.message));
  return p;
}

// `let` + ESM live bindings: importers keep seeing the current pool after a
// transport switch, so `import { pool }` and `db.pool.query(...)` stay valid.
export let pool = buildPool();

export const q = (text, params) => pool.query(text, params);

/** What we ended up connected to — for logs, /status and the health endpoint. */
let info = { connected: false, url: redactUrl(dbUrl), source: dbSource, ssl: sslLabel(ssl) };
export const dbInfo = () => ({ ...info });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function switchSsl(next, why) {
  if (sslLabel(ssl) === sslLabel(next)) return false;
  log.warn(`server says TLS should be ${sslLabel(next)} (${why}) — reconnecting`);
  ssl = next;
  const old = pool;
  pool = buildPool();
  try { await old.end(); } catch {}
  return true;
}

/**
 * Open the database, and keep trying.
 *
 * Two things make a deploy fail where localhost succeeds. The container boots
 * before the platform's private network resolves, so the very first connection
 * loses a race it will win a second later — hence the backoff. And the
 * transport may not be what the URL implies — hence the probe and the
 * mid-flight correction. Both are recoverable, so neither should be fatal.
 */
export async function connect({ attempts = CONNECT_ATTEMPTS, baseDelayMs = 1000 } = {}) {
  const problems = validateUrl(dbUrl, dbSource);
  if (problems.length) {
    const e = new Error(problems[0]);
    e.hints = problems.slice(1);
    e.fatal = true;
    throw e;
  }

  const target = parseTarget(dbUrl);
  log.info(`connecting to ${redactUrl(dbUrl)} (from ${dbSource}), ssl ${sslLabel(ssl)} — ${policy.reason}`);

  // Ask the server what it actually speaks instead of trusting the hostname
  // (or the URL, which is usually copied from somewhere else).
  if (!sslPinned && target) {
    const supports = await probeSsl(target.host, target.port);
    if (supports === true && ssl === false) await switchSsl({ rejectUnauthorized: false }, 'handshake probe');
    if (supports === false && ssl !== false) {
      if (policy.explicit) log.warn(`${policy.reason}, but ${target.host} does not offer TLS — overriding`);
      await switchSsl(false, 'handshake probe');
    }
  }

  let lastErr;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const client = await pool.connect();
      try {
        const { rows } = await client.query(
          'SELECT current_database() AS db, current_user AS "user", version() AS version',
        );
        const server = String(rows[0].version).split(' ').slice(0, 2).join(' ');
        info = {
          connected: true,
          url: redactUrl(dbUrl),
          source: dbSource,
          ssl: sslLabel(ssl),
          database: rows[0].db,
          user: rows[0].user,
          server,
          host: target?.host,
        };
        log.info(`connected — ${server}, db ${rows[0].db} as ${rows[0].user}, ssl ${sslLabel(ssl)}`);
        return dbInfo();
      } finally {
        client.release();
      }
    } catch (e) {
      lastErr = e;

      // "You knocked on the wrong door" — retry immediately on the right one,
      // without spending an attempt.
      const fix = sslPinned ? null : sslCorrection(e);
      if (fix && await switchSsl(fix === 'off' ? false : { rejectUnauthorized: false }, e.message)) {
        attempt--;
        continue;
      }

      if (!isRetryable(e) || attempt === attempts) break;
      const delay = Math.min(baseDelayMs * 2 ** (attempt - 1), 8000);
      log.warn(`connect attempt ${attempt}/${attempts} failed (${e.code || e.message}) — retrying in ${delay}ms`);
      await sleep(delay);
    }
  }

  const { headline, hints } = explainDbError(lastErr, { url: dbUrl, source: dbSource, ssl });
  const err = new Error(headline);
  err.cause = lastErr;
  err.hints = hints;
  throw err;
}

/**
 * Shut the pool down, once.
 *
 * Always prefer this to `pool.end()`: a TLS switch replaces the pool, and any
 * caller that destructured `pool` at import time is holding the retired one —
 * ending that twice throws "Called end on pool more than once".
 */
export async function close() {
  const p = pool;
  if (!p || p.ended || p.ending) return;
  try { await p.end(); } catch (e) { log.warn(`pool close: ${e.message}`); }
}


export async function migrate() {
  const sql = fs.readFileSync(path.join(__dirname, 'schema.sql'), 'utf8');
  await q(sql);
  log.info('schema ready');
}

// ------------------------------------------------------------------ settings

let settingsCache = null;

export async function loadSettings() {
  const { rows } = await q('SELECT key, value FROM agent_settings');
  const s = { ...config.defaults };
  for (const r of rows) s[r.key] = r.value;
  settingsCache = s;
  return s;
}

export function settings() {
  return settingsCache || { ...config.defaults };
}

export async function seedSettings() {
  for (const [k, v] of Object.entries(config.defaults)) {
    await q(
      `INSERT INTO agent_settings (key, value) VALUES ($1, $2::jsonb)
       ON CONFLICT (key) DO NOTHING`,
      [k, JSON.stringify(v)],
    );
  }
  return loadSettings();
}

/**
 * Change a setting.
 *
 * The in-memory cache is updated FIRST and unconditionally, so a setting
 * always takes effect immediately — even if Neon is unreachable. Losing the
 * database must never stop you from turning auto trading off: that is the kill
 * switch. Persistence failures are reported, not thrown.
 *
 * @returns {{settings: object, persisted: boolean, error: string|null}}
 */
export async function setSetting(key, value, by = 'user') {
  settingsCache = { ...settings(), [key]: value };

  try {
    await q(
      `INSERT INTO agent_settings (key, value, updated_by, updated_at)
       VALUES ($1, $2::jsonb, $3, now())
       ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_by = EXCLUDED.updated_by, updated_at = now()`,
      [key, JSON.stringify(value), by],
    );
  } catch (e) {
    log.warn(`setSetting(${key}) not persisted: ${e.message} — applied in memory only`);
    return { settings: settings(), persisted: false, error: e.message };
  }

  try {
    await loadSettings();
  } catch (e) {
    log.warn(`settings reload failed: ${e.message}`);
  }
  return { settings: settings(), persisted: true, error: null };
}

