/* ------------------------------------------------------------------ sessions
 *
 * A session is a bookmark, not a copy. Resuming one sets the conversation
 * window the agent reads from back to that point instead of the last N
 * messages, so "go back to where we were discussing the funding squeeze"
 * actually restores that context.
 */

/** Create a session bookmark at the current end of the conversation. */
export async function createSession({ chatId, name, note = null, coversUntil = null }) {
  if (!chatId || !name) throw new Error('createSession needs chatId and name');
  let until = coversUntil;
  if (until == null) {
    const r = await q('SELECT COALESCE(MAX(id), 0) AS id FROM conversations WHERE chat_id = $1', [chatId]);
    until = Number(r.rows[0]?.id || 0);
  }
  const cnt = await countMessagesSince(chatId, until);
  const { rows } = await q(
    `INSERT INTO sessions (chat_id, name, note, covers_until, messages)
     VALUES ($1, $2, $3, $4, $5) RETURNING *`,
    [chatId, String(name).slice(0, 80), note, until, cnt],
  );
  return rows[0];
}

/** List a chat's sessions, most recently useful first. */
export async function listSessions(chatId, limit = 10) {
  const { rows } = await q(
    `SELECT s.*,
            (SELECT COUNT(*) FROM conversations c
              WHERE c.chat_id = s.chat_id AND c.id > s.covers_until) AS since_msgs
       FROM sessions s
      WHERE s.chat_id = $1
      ORDER BY COALESCE(s.last_resumed, s.created_at) DESC
      LIMIT $2`,
    [chatId, limit],
  );
  return rows;
}

/**
 * Mark a session as resumed. The agent's own window is restored by
 * summarising everything after covers_until into the session note, which is
 * what "resume" means in practice — see the caller in commands.js.
 */
export async function touchSession(id) {
  const { rows } = await q(
    `UPDATE sessions SET last_resumed = now() WHERE id = $1 RETURNING *`, [id],
  );
  return rows[0] || null;
}

/** Delete one session. The conversation itself is untouched. */
export async function deleteSession(id) {
  const { rowCount } = await q('DELETE FROM sessions WHERE id = $1', [id]);
  return rowCount > 0;
}

/** Every message after a session's bookmark — what would be re-injected. */
export async function sessionTail(sessionId, limit = 60) {
  const { rows: s } = await q('SELECT * FROM sessions WHERE id = $1', [sessionId]);
  if (!s[0]) return null;
  const { rows } = await q(
    `SELECT * FROM conversations
      WHERE chat_id = $1 AND id > $2
      ORDER BY id ASC LIMIT $3`,
    [s[0].chat_id, s[0].covers_until, limit],
  );
  return { session: s[0], messages: rows };
}

import { config } from '../config.js';
import { createLogger } from '../logger.js';
import { chunk } from './format.js';

const log = createLogger('telegram');

/**
 * Minimal dependency-free Telegram Bot API client with long polling.
 *
 * Robust sending: MarkdownV2 first, and if Telegram rejects the entities
 * (the classic "can't parse entities" 400 that silently killed reports in the
 * reference scanner) it automatically retries as plain text, then as a
 * truncated plain text. A message is never lost.
 */
export class TelegramBot {
  constructor(token = config.telegram.token) {
    this.token = token;
    this.api = `https://api.telegram.org/bot${token}`;
    this.offset = 0;
    this.handlers = [];
    this.running = false;
    this.me = null;
    // Set when Telegram auth fails at boot. The trader keeps running with no
    // Telegram at all: sends become rate-limited no-ops and polling never
    // starts. A broken bot token must never take the position manager down
    // with it — that is how an unreachable notification channel turns into
    // unmanaged live positions.
    this.degraded = false;
    this.degradedReason = null;
    this._lastDegradedWarn = 0;
  }

  /** Record that Telegram is unreachable, and stop hammering the API. */
  _degrade(reason) {
    if (!this.degraded) {
      this.degraded = true;
      this.degradedReason = reason;
      this.running = false;
      log.error(
        `telegram unavailable (${reason}) — continuing WITHOUT Telegram. `
        + `Trading, scanning and position management stay ON, but reports and `
        + `/commands are unavailable until TELEGRAM_BOT_TOKEN is fixed.`,
      );
    }
  }

  async call(method, payload = {}) {
    let res;
    try {
      res = await fetch(`${this.api}/${method}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(70_000),
      });
    } catch (e) {
      // Network/DNS/timeout, not an API-level rejection. Surface the real cause
      // rather than a JSON parse error from an HTML error page.
      throw new Error(`${method}: ${e.message}`);
    }
    const json = await res.json().catch(() => ({ ok: false, description: `HTTP ${res.status}` }));
    if (!json.ok) {
      const err = new Error(`${method}: ${json.description}`);
      err.description = json.description;
      err.code = json.error_code;
      throw err;
    }
    return json.result;
  }

  async sendMessage(chatId, text, { parseMode = 'MarkdownV2', ...extra } = {}) {
    if (this.degraded) {
      const now = Date.now();
      if (now - this._lastDegradedWarn > 10 * 60_000) {
        this._lastDegradedWarn = now;
        log.warn(`dropping telegram message to ${chatId} — telegram is degraded (${this.degradedReason})`);
      }
      return [];
    }
    const parts = chunk(text);
    const sent = [];
    for (const part of parts) {
      try {
        sent.push(await this.call('sendMessage', {
          chat_id: chatId, text: part, parse_mode: parseMode,
          disable_web_page_preview: true, ...extra,
        }));
      } catch (e) {
        // FIX: entity parse failures must never swallow the message
        if (/can't parse entities|Bad Request/i.test(e.description || e.message)) {
          log.warn(`markdown rejected (${e.description}) — resending as plain text`);
          const plain = part.replace(/\\([_*[\]()~`>#+\-=|{}.!\\])/g, '$1');
          try {
            sent.push(await this.call('sendMessage', {
              chat_id: chatId, text: plain, disable_web_page_preview: true, ...extra,
            }));
          } catch (e2) {
            log.error(`plain resend also failed: ${e2.message}`);
            try {
              sent.push(await this.call('sendMessage', {
                chat_id: chatId, text: plain.slice(0, 3500),
              }));
            } catch (e3) { log.error(`message lost: ${e3.message}`); }
          }
        } else {
          log.error(`sendMessage failed: ${e.message}`);
        }
      }
    }
    return sent;
  }

  async sendTyping(chatId) {
    try { await this.call('sendChatAction', { chat_id: chatId, action: 'typing' }); } catch {}
  }

  onMessage(fn) { this.handlers.push(fn); }

  allowed(chatId) {
    const list = config.telegram.allowed;
    if (!list.length) return true;   // no allowlist = open (set one in production!)
    return list.includes(String(chatId));
  }

  async setCommands() {
    try {
      await this.call('setMyCommands', {
        commands: [
          { command: 'start', description: 'Wake the agent up' },
          { command: 'help', description: 'All commands' },
          { command: 'status', description: 'Agent, exchange and model status' },
          { command: 'balance', description: 'Futures balance' },
          { command: 'positions', description: 'Open positions' },
          { command: 'position_history', description: 'Closed positions' },
          { command: 'order_history', description: 'Past orders' },
          { command: 'pnl', description: 'Performance summary' },
          { command: 'signal', description: 'Scan the market now' },
          { command: 'analyse', description: 'Deep analysis of a symbol' },
          { command: 'deep', description: '5-phase multi-agent analysis' },
          { command: 'close', description: 'Close a position' },
          { command: 'closeall', description: 'Close every position' },
          { command: 'auto_trade', description: 'Turn auto trading on or off' },
          { command: 'scan', description: 'Scan now or on/off' },
          { command: 'report', description: 'Reports on or off' },
          { command: 'settings', description: 'All trade settings' },
          { command: 'set', description: 'Change a setting' },
          { command: 'leverage', description: 'Show or set leverage' },
          { command: 'model', description: 'Show or pin the AI model' },
          { command: 'models', description: 'Manage AI models' },
          { command: 'check_system', description: 'System health check' },
          { command: 'connect_provider', description: 'Configure AI provider' },
          { command: 'set_model', description: 'Pin a specific model' },
          { command: 'add_soul', description: 'Add a soul file' },
          { command: 'add_skill', description: 'Add a skill file' },
          { command: 'add_mcp', description: 'Add MCP server config' },
          { command: 'mcp', description: 'External MCP servers and tools' },
          { command: 'memory', description: 'What the agent has learned' },
          { command: 'skills', description: 'Teach or manage skills' },
          { command: 'code_review', description: 'Review codebases for issues' },
          { command: 'bug_fixes', description: 'Analyze bugs' },
          { command: 'simplfy', description: 'Simplify code analysis' },
          { command: 'verify', description: 'Verify a specific component' },
          { command: 'reload', description: 'Re-read soul/ from disk' },
          { command: 'diag', description: 'Test the notification chain' },
        ],
      });
    } catch (e) { log.warn(`setMyCommands: ${e.message}`); }
  }

  async start() {
    try {
      this.me = await this.call('getMe');
      log.info(`connected as @${this.me.username}`);
      await this.setCommands();
      this.running = true;
      this._poll();
    } catch (e) {
      // A bad token is a config error, not a reason to abandon live positions.
      // Degrade: the caller decides whether to keep going; nothing throws.
      this._degrade(e.message);
      return null;
    }
    return this.me;
  }

  async _poll() {
    while (this.running) {
      try {
        const updates = await this.call('getUpdates', {
          offset: this.offset, timeout: 50, allowed_updates: ['message', 'callback_query'],
        });
        for (const u of updates) {
          this.offset = u.update_id + 1;
          const msg = u.message;
          if (!msg?.text) continue;
          if (!this.allowed(msg.chat.id)) {
            await this.sendMessage(msg.chat.id, 'Not authorised\\.', {});
            continue;
          }
          for (const h of this.handlers) {
            h(msg).catch((e) => log.error(`handler: ${e.stack || e.message}`));
          }
        }
      } catch (e) {
        // 401/403 means the token is bad or revoked. Polling forever would spin
        // every 2s and burn the quota; degrade and let the trader run.
        if (e.code === 401 || e.code === 403 || /Unauthorized|bot was blocked|bot is deactivated/i.test(e.message)) {
          this._degrade(e.message);
          return;
        }
        if (!/timeout|aborted/i.test(e.message)) log.warn(`poll: ${e.message}`);
        await new Promise((r) => setTimeout(r, 2000));
      }
    }
  }

  stop() { this.running = false; }
}

export default TelegramBot;

/**
 * Telegram formatting helpers.
 *
 * THE BUG THIS FIXES:
 * the reference scanner sent MarkdownV2/Markdown text containing raw
 * `_`, `*`, `[`, `` ` `` coming from symbols, strategy names ("vwap_reversion",
 * "min_confidence") and JSON dumps. Telegram then rejected the whole message
 * with 400 "can't parse entities" and the export/report silently never arrived.
 *
 * Strategy here:
 *  - build messages in MarkdownV2
 *  - escape EVERY dynamic value with md()
 *  - hard-fail-safe: sendMessage retries as plain text if Telegram still
 *    complains, so a report is never lost
 */

// Every message that reports an agreement count has to know how many
// strategies could have voted. Hardcoding 6 turned every report into a lie the
// moment a strategy was added, and the scan loop crashed on the bare
// identifier because this module never imported it.
import { STRATEGY_COUNT } from '../strategies/index.js';

const MDV2_SPECIALS = /[_*[\]()~`>#+\-=|{}.!\\]/g;

/** Escape a dynamic value for MarkdownV2. */
export const md = (v) => String(v ?? '').replace(MDV2_SPECIALS, '\\$&');

/** Escape only what breaks inside a code span. */
export const code = (v) => '`' + String(v ?? '').replace(/[`\\]/g, '\\$&') + '`';

export const bold = (v) => `*${md(v)}*`;
export const italic = (v) => `_${md(v)}_`;

/**
 * Template tag that escapes BOTH the static text and the interpolations.
 *
 * Escaping only the interpolations (what the reference scanner did) is not
 * enough: literal `(`, `)`, `/6`, `—`, `.` and `!` in the template itself are
 * also MarkdownV2 entities and produce the same 400 error. Everything inside
 * mdt`` is therefore treated as plain text; use bold()/italic() explicitly when
 * you want emphasis.
 */
export function mdt(strings, ...values) {
  return strings.reduce(
    (acc, s, i) => acc + md(s) + (i < values.length ? md(values[i]) : ''),
    '',
  );
}

/**
 * Convert free-form LLM markdown into SAFE MarkdownV2.
 *
 * The agent writes classic markdown (**bold**, *bold*, _italic_, `code`,
 * - bullets, ### headings). Sending that straight to Telegram is exactly what
 * breaks reports: stray `*`, `_`, `.`, `-`, `(` all count as entities.
 *
 * Here we: pull out code spans/blocks, escape everything else, then restore a
 * whitelist of *balanced* emphasis pairs and the code spans.
 */
export function agentText(input) {
  if (!input) return '';
  let text = String(input);

  // 1. stash code blocks and inline code
  const stash = [];
  const keep = (s) => { stash.push(s); return `\u0000${stash.length - 1}\u0000`; };
  text = text.replace(/```[\s\S]*?```/g, (m) => keep(m));
  text = text.replace(/`[^`\n]+`/g, (m) => keep(m));

  // 2. normalise headings and ** -> * before escaping
  text = text.replace(/^#{1,6}\s*(.+)$/gm, (_, t) => `\u0001${t.trim()}\u0001`); // heading -> bold
  text = text.replace(/\*\*([^\n*]+)\*\*/g, (_, t) => `\u0001${t}\u0001`);       // **bold** -> bold
  text = text.replace(/(?<![\w*])\*([^\n*]+)\*(?![\w*])/g, (_, t) => `\u0001${t}\u0001`);
  text = text.replace(/(?<![\w_])_([^\n_]+)_(?![\w_])/g, (_, t) => `\u0002${t}\u0002`);
  text = text.replace(/^\s*[-*+]\s+/gm, '\u0003 ');                              // bullets

  // 3. escape EVERYTHING
  text = md(text);

  // 4. restore the whitelisted markers
  text = text
    .replace(/\u0001/g, '*')
    .replace(/\u0002/g, '_')
    .replace(/\u0003/g, '•');

  // 5. restore code, escaping only what breaks inside it
  text = text.replace(/\u0000(\d+)\u0000/g, (_, i) => {
    const raw = stash[Number(i)];
    if (raw.startsWith('```')) {
      const body = raw.slice(3, -3).replace(/\\/g, '\\\\').replace(/`/g, '\\`');
      return '```' + body + '```';
    }
    return '`' + raw.slice(1, -1).replace(/\\/g, '\\\\').replace(/`/g, '\\`') + '`';
  });

  return text;
}

export function fmtNum(v, digits = 4) {
  const n = Number(v);
  if (!Number.isFinite(n)) return '—';
  if (Math.abs(n) >= 1000) return n.toFixed(2);
  if (Math.abs(n) >= 1) return n.toFixed(digits);
  return n.toPrecision(Math.max(4, digits));
}

export const pct = (v, d = 2) => `${Number(v) >= 0 ? '+' : ''}${Number(v).toFixed(d)}%`;
export const usd = (v, d = 4) => `${Number(v) >= 0 ? '+' : ''}${Number(v).toFixed(d)} USDT`;

/** Split long text on line boundaries so nothing is truncated by Telegram's 4096 limit. */
export function chunk(text, size = 3800) {
  if (text.length <= size) return [text];
  const out = [];
  let cur = '';
  for (const line of text.split('\n')) {
    if (cur.length + line.length + 1 > size) { out.push(cur); cur = ''; }
    // a single monstrous line
    if (line.length > size) {
      for (let i = 0; i < line.length; i += size) out.push(line.slice(i, i + size));
      continue;
    }
    cur += (cur ? '\n' : '') + line;
  }
  if (cur) out.push(cur);
  return out;
}

// ------------------------------------------------------------------ messages

export function formatSignal(s) {
  const emoji = s.side === 'LONG' ? '🟩' : '🟥';
  const lines = [
    `${emoji} ${bold(`${s.symbol} ${s.side}`)}`,
    mdt`confidence ${s.confidence}%  ·  agreement ${s.agreement}/${STRATEGY_COUNT}  ·  regime ${s.regime} (HTF ${s.htfRegime || '—'})`,
    mdt`raw ${s.rawConfidence || s.confidence}% · scanned ${new Date().toLocaleTimeString('en', {hour12:false})}`,
    mdt`price ${fmtNum(s.price, 6)}  ·  ATR ${Number(s.atrPct || 0).toFixed(3)}%${s.funding != null ? `  ·  funding ${Number(s.funding).toFixed(4)}%` : ''}`,
    '',
    bold('Strategies'),
    // A signal can reach here with no strategies at all: consensus() returns
    // null before it can, but a hand-built or persisted row may not carry them,
    // and an unguarded .map took the whole report down with it.
    ...(s.strategies || []).map((x) => mdt`  • ${x.name} — ${x.confidence}% on ${(x.timeframes || []).join(', ')}`),
  ];
  if (s.opposite?.agreement) {
    lines.push(mdt`  ⚠ ${s.opposite.agreement} opposing (${s.opposite.side} @ ${s.opposite.confidence}%)`);
  }
  if (s.flags?.length) lines.push('', mdt`flags: ${s.flags.join('; ')}`);
  if (!s.qualified) lines.push('', mdt`⛔ not taken — ${s.rejectReason}`);
  return lines.join('\n');
}

export function formatFill(r) {
  return [
    `⚡ ${bold(`OPENED ${r.symbol} ${r.side}`)}`,
    mdt`entry ${fmtNum(r.price, 6)}  ·  qty ${r.qty}  ·  margin ${Number(r.marginUsdt).toFixed(2)} USDT  ·  ${r.leverage}x`,
    r.leverageAdjusted
      ? mdt`⚠️ leverage adjusted from ${r.requestedLeverage}x to ${r.leverage}x — ${r.leverageAdjustmentReason || 'exchange/risk limits'}`
      : '',
    mdt`TP ${fmtNum(r.tpPrice, 6)}  ·  SL ${fmtNum(r.slPrice, 6)}  ·  ${r.risk.rr}R`,
    mdt`${r.risk.explain}`,
    r.positionId ? mdt`position ${r.positionId}` : '',
  ].filter(Boolean).join('\n');
}

export function formatPositions(snap) {
  if (!snap.count) return '📭 No open positions\\.';
  const head = [
    bold('Open positions'),
    mdt`${snap.count} open  ·  margin ${snap.totalMargin.toFixed(2)} USDT  ·  uPnL ${usd(snap.totalPnl)}  ·  ROI ${pct(snap.roi)}`,
    '',
  ];
  const body = (snap.positions || []).map((p) => {
    const e = Number(p.unrealizedPNL || 0) >= 0 ? '🟢' : '🔴';
    // Every field is read through a numeric guard: a position row missing
    // `margin` or `marginMode` used to throw here and take the whole /positions
    // view down, rather than showing the row with a "—" where the gap is.
    const margin = Number(p.margin);
    const mode = p.marginMode ? ` ${p.marginMode}` : '';
    const liq = Number(p.liqPrice);
    return [
      `${e} ${bold(`${p.symbol} ${p.side}`)} ${md(`${p.leverage}x${mode}`)}`,
      mdt`   qty ${p.qty ?? '?'}  ·  entry ${fmtNum(p.avgOpenPrice, 6)}  ·  liq ${Number.isFinite(liq) && liq > 0 ? fmtNum(liq, 6) : '—'}`,
      mdt`   margin ${Number.isFinite(margin) ? margin.toFixed(2) : '—'}  ·  uPnL ${usd(p.unrealizedPNL)}  ·  ROI ${pct(p.roi)}`,
      mdt`   id ${p.positionId ?? '—'}`,
    ].join('\n');
  });
  return head.concat(body).join('\n');
}

export function formatBalance(b) {
  return [
    bold('Balance'),
    mdt`available   ${Number(b.available).toFixed(4)} USDT`,
    mdt`in margin   ${Number(b.margin).toFixed(4)} USDT`,
    mdt`frozen      ${Number(b.frozen).toFixed(4)} USDT`,
    mdt`unrealised  ${usd(b.unrealized)}`,
    mdt`bonus       ${Number(b.bonus).toFixed(4)} USDT`,
    mdt`mode        ${b.positionMode}`,
  ].join('\n');
}

