function pct(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return '—';
  return (n >= 0 ? '+' : '') + n.toFixed(2) + '%';
}
function usd(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return '—';
  return (n >= 0 ? '+' : '') + n.toFixed(2) + ' USDT';
}

function pill(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return '<span class="pill neutral">—</span>';
  const cls = n > 0 ? 'ok' : (n < 0 ? 'neg' : 'neutral');
