    kpis.innerHTML = `
      <div class="tile"><div class="label">DB</div><div class="value">${st.db.connected ? '●' : '○'}</div><div class="sub">${st.db.connected ? 'connected' : 'disconnected'}</div></div>
      <div class="tile"><div class="label">Auto trade</div><div class="value ${st.settings.auto_trade ? 'pos' : 'neg'}">${st.settings.auto_trade ? 'ON' : 'OFF'}</div></div>
      <div class="tile"><div class="label">Scanner</div><div class="value ${st.orchestrator.scanningEnabled ? 'pos' : 'neg'}">${st.orchestrator.scanningEnabled ? 'ON' : 'OFF'}</div></div>
      <div class="tile"><div class="label">Symbols</div><div class="value">${st.settings.symbols || 'AUTO'}</div></div>
      <div class="tile"><div class="label">Leverage</div><div class="value">${st.settings.leverage}x</div></div>
    `;
  } catch (e) {
    showErr('status', e.message);
  }
}

/* ---------- settings ---------- */
async function refreshSettings() {
  try {
    const data = await api('/api/settings');
    const list = $('settings-list');
    list.innerHTML = '';
    const groups = {};
    const order = ['Trading','TP / SL','Signal gates','Reversal','Protection','Intervals','Agent','Settings'];
    // Use flat list since server returns raw settings; group by key prefix hints
    const keys = Object.keys(data.settings || {}).sort();
    for (const k of keys) {
      const v = data.settings[k];
      const info = (data.defaults && data.defaults[k]) ? null : null;
      const el = document.createElement('div');
      el.className = 'setting';
      el.dataset.key = k;
      let input;
      if (typeof v === 'boolean') {
        input = document.createElement('select');
        input.innerHTML = '<option value="true">true</option><option value="false">false</option>';
        input.value = String(v);
      } else if (Array.isArray(v)) {
        input = document.createElement('input');
        input.type = 'text';
        input.value = v.join(',');
      } else {
        input = document.createElement('input');
        input.type = 'text';
        input.value = String(v);
      }
      const save = document.createElement('button');
      save.className = 'save';
      save.textContent = 'save';
      save.onclick = () => saveSetting(k, input.value, save);
      input.oninput = () => { save.classList.add('show'); $(`msg-${k}`)?.remove(); };
      const desc = document.createElement('div');
      desc.className = 'desc';
      desc.textContent = (SETTING_DESC[k] && SETTING_DESC[k][0]) || '';
      const range = document.createElement('div');
      range.className = 'range';
      range.textContent = (SETTING_DESC[k] && SETTING_DESC[k][1]) || '';
      const keydiv = document.createElement('div');
      keydiv.className = 'key';
      keydiv.textContent = k;
      el.appendChild(keydiv);
      el.appendChild(desc);
      el.appendChild(range);
      el.appendChild(input);
      el.appendChild(save);
      list.appendChild(el);
    }
    $('settings-msg').innerHTML = '';
  } catch (e) {
    showErr('settings-msg', e.message);
  }
}

async function saveSetting(key, raw, btn) {
  const errId = 'msg-' + key;
  let old = document.getElementById(errId);
  if (old) old.remove();
  btn.classList.remove('show');
  btn.classList.add('saving');
  btn.disabled = true;
  try {
    const res = await api('/api/settings/' + encodeURIComponent(key), { method: 'POST', body: { value: raw } });
    const el = document.querySelector('.setting[data-key="' + CSS.escape(key) + '"]');
    const msg = document.createElement('div');
    msg.id = errId;
    msg.className = res.error ? 'err' : '';
    msg.textContent = res.error || ('persisted: ' + (res.persisted ? 'yes' : 'no (in memory only)'));
    if (el) el.appendChild(msg);
    if (!res.error) {
      btn.classList.remove('show');
      setTimeout(() => { if (btn) btn.classList.remove('show'); }, 1200);
    }
  } catch (e) {
    const msg = document.createElement('div');
    msg.id = errId;
    msg.className = 'err';
    msg.textContent = e.message;
    if (el) el.appendChild(msg);
  } finally {
    btn.classList.remove('saving');
    btn.disabled = false;
  }
}

/* ---------- positions ---------- */
async function refreshPositions() {
  try {
    const data = await api('/api/positions');
    const body = $('positions-body');
    const empty = $('positions-empty');
    body.innerHTML = '';
    const positions = data.positions || [];
    if (positions.length) {
      empty.style.display = 'none';
      for (const p of positions) {
        const upnl = p.unrealizedPNL != null ? Number(p.unrealizedPNL) : 0;
        const roi = p.roi != null ? Number(p.roi) : 0;
        const sideCls = p.side === 'LONG' ? 'pos' : 'neg';
        const row = document.createElement('tr');
        row.innerHTML = `
          <td><span class="mono">${escapeHtml(p.symbol)}</span></td>
          <td><span class="pill ${sideCls}">${escapeHtml(p.side)}</span></td>
          <td class="num">${Number(p.leverage || 0).toFixed(0)}x</td>
          <td class="num mono">${p.entry_price != null ? p.entry_price.toFixed(6) : '—'}</td>
          <td class="num mono">${p.qty != null ? p.qty.toFixed(6) : '—'}</td>
          <td class="num ${upnl >= 0 ? 'pos' : 'neg'}">${usd(upnl)}</td>
          <td class="num ${roi >= 0 ? 'pos' : 'neg'}">${pct(roi)}</td>
          <td class="mono">${p.tp_price ? p.tp_price.toFixed(6) : '—'} / ${p.sl_price ? p.sl_price.toFixed(6) : '—'}</td>
          <td class="row-actions">
            <button class="btn small btn-danger" onclick="closePosition('${escapeHtml(p.symbol)}','${escapeHtml(String(p.position_id || p.id))}')">close</button>
          </td>
        `;
        body.appendChild(row);
      }
    } else {
      empty.style.display = 'block';
    }
  } catch (e) {
    showErr('positions', e.message);
  }
}

/* ---------- signals ---------- */
async function refreshSignals() {
  try {
    const data = await api('/api/signals');
    const body = $('signals-body');
    const empty = $('signals-empty');
    body.innerHTML = '';
    const signals = data.signals || [];
    if (signals.length) {
      empty.style.display = 'none';
      for (const s of signals) {
        const conf = Number(s.confidence || 0);
        const cls = conf >= 80 ? 'ok' : (conf >= 60 ? 'warn' : 'bad');
        const taken = s.taken ? '<span class="pill ok">yes</span>' : '<span class="pill bad">no</span>';
        const reject = s.reject_reason ? escapeHtml(s.reject_reason) : '—';
        const row = document.createElement('tr');
        row.innerHTML = `
          <td class="mono">${fmtTime(s.created_at)}</td>
          <td class="mono">${escapeHtml(s.symbol)}</td>
          <td><span class="pill ${s.side === 'LONG' ? 'pos' : 'neg'}">${escapeHtml(s.side)}</span></td>
          <td class="num"><span class="pill ${cls}">${conf}%</span></td>
          <td class="num">${s.agreement != null ? s.agreement + '/10' : '—'}</td>
          <td class="mono">${escapeHtml(s.regime || '—')}</td>
          <td>${taken}</td>
          <td class="long">${reject}</td>
        `;
        body.appendChild(row);
      }
    } else {
      empty.style.display = 'block';
    }
  } catch (e) {
    showErr('signals', e.message);
  }
}

/* ---------- trades ---------- */
async function refreshTrades() {
  try {
    const data = await api('/api/trades');
    const body = $('trades-body');
    const empty = $('trades-empty');
    body.innerHTML = '';
    const trades = data.open || [];
    const stats = data.stats || {};
    $('stat-trades').textContent = stats.trades ?? '—';
    $('stat-winloss').textContent = `${stats.wins ?? '—'} / ${stats.losses ?? '—'}`;
    const pnl = Number(stats.pnl || 0);
    $('stat-pnl').textContent = usd(pnl);
    $('stat-pnl').className = pnl >= 0 ? 'pos' : 'neg';
    if (trades.length) {
      empty.style.display = 'none';
      for (const t of trades) {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td class="mono">${fmtDate(t.opened_at)}</td>
          <td class="mono">${escapeHtml(t.symbol)}</td>
          <td><span class="pill ${t.side === 'LONG' ? 'pos' : 'neg'}">${escapeHtml(t.side)}</span></td>
          <td class="num mono">${t.entry_price != null ? Number(t.entry_price).toFixed(6) : '—'}</td>
          <td class="num mono">${t.qty != null ? Number(t.qty).toFixed(6) : '—'}</td>
          <td class="mono">${t.tp_price ? Number(t.tp_price).toFixed(6) : '—'} / ${t.sl_price ? Number(t.sl_price).toFixed(6) : '—'}</td>
          <td><span class="pill neutral">${escapeHtml(t.status || 'OPEN')}</span></td>
        `;
        body.appendChild(row);
      }
    } else {
      empty.style.display = 'block';
    }
  } catch (e) {
    showErr('trades', e.message);
  }
}

/* ---------- events ---------- */
async function refreshEvents() {
  try {
    const data = await api('/api/events');
    const body = $('events-body');
    const empty = $('events-empty');
    body.innerHTML = '';
    const events = data.events || [];
    if (events.length) {
      empty.style.display = 'none';
      for (const e of events) {
        const row = document.createElement('tr');
        let payload = '—';
        try { payload = typeof e.payload === 'string' ? e.payload : JSON.stringify(e.payload); } catch {}
        row.innerHTML = `
          <td class="mono">${fmtTime(e.created_at)}</td>
          <td class="mono">${escapeHtml(e.kind)}</td>
          <td class="mono">${escapeHtml(e.symbol || '—')}</td>
          <td class="long mono">${escapeHtml(payload).slice(0, 200)}</td>
        `;
        body.appendChild(row);
      }
    } else {
      empty.style.display = 'block';
    }
  } catch (err) {
    showErr('events', err.message);
  }
}

/* ---------- commands ---------- */
async function toggleCommand(name) {
  try {
    const btn = name === 'scan' ? $('btn-scan') : $('btn-report');
    const cur = btn.textContent.includes(': ON');
    const res = await api('/api/command/' + name, { method: 'POST', body: { enabled: !cur } });
    if (res.error) { alert('Failed: ' + res.error); return; }
    refreshStatus();
  } catch (e) { alert('Failed: ' + e.message); }
}

async function killSwitch() {
  if (!confirm('This disables auto trading immediately. Open positions stay open but no new entries will be taken. Continue?')) return;
  try {
    await api('/api/command/kill', { method: 'POST', body: {} });
    refreshStatus();
    refreshSettings();
    showOk('settings-msg', 'Auto trading disabled (kill switch).');
  } catch (e) { alert('Failed: ' + e.message); }
}

async function closePosition(symbol, positionId) {
  if (!confirm(`Close position ${symbol} (${positionId})?`)) return;
  // Close via dashboard server command endpoint if available; otherwise notify user to use Telegram.
  alert('Use /close ' + symbol + ' in Telegram, or add a close endpoint to the dashboard.');
}

/* ---------- ui helpers ---------- */
function showOk(where, text) {
  const el = $(where);
  if (!el) return;
  el.innerHTML = '<div class="msg ok">' + escapeHtml(text) + '</div>';
  setTimeout(() => el.innerHTML = '', 3000);
}
function showErr(where, text) {
  const el = $(where);
  if (!el) return;
  el.innerHTML = '<div class="msg err">' + escapeHtml(text) + '</div>';
}

/* ---------- tabs ---------- */
document.querySelectorAll('.tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.tabcontent').forEach(tc => tc.classList.remove('active'));
    tab.classList.add('active');
    $(`tab-${tab.dataset.tab}`).classList.add('active');
  });
});

/* ---------- poll ---------- */
async function tick() {
  await refreshStatus();
  await refreshSettings();
  await refreshPositions();
  await refreshSignals();
  await refreshTrades();
  await refreshEvents();
}
function startPoll() { if (polling) clearInterval(polling); polling = setInterval(tick, 4000); tick(); }
startPoll();

</script>
</body>
</html>
"}

